    { id:"p3h-390", category: "historia", difficulty: "svår", tags: ["p3-historia"], question: "Vad lät änkekejsarinnan Cixi bygga i marmor vid Sommarpalatset i Peking?", answer: "En båt", accept: ["en båt","marmorbåten","båt"], explanation: "Den sägs ha finansierats med pengar avsedda för flottan.", sources: ["sv:Sommarpalatset"] },
    { id:"p3h-391", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vilken pojke utsåg änkekejsarinnan Cixi till kejsare 1908, strax innan hon dog?", answer: "Puyi", accept: ["puyi","pu yi"], explanation: "Han blev Kinas siste kejsare.", sources: ["sv:Puyi"] }
